/* 학습 해설
 * Alternative module과kernel쓰기·alias선택
 * 원본300행의주소복원·분기와page재배치·callback·mask·alias·cache·ELFregion·boot/system/module동기화와사용계약을읽습니다.
 * origptr은 descriptor의원본위치입니다. module이면 updptr=origptr이고 kernel이면 lm_alias(origptr)를사용합니다. 원본 text위치와쓰기경로주소의분리로 instruction주소재계산을유지합니다. patchcallback에는둘을모두전달합니다. 이 helper자체가 moduletextpermission전환을구현한다고추론하면안됩니다.
 * is_moduletrue/false두경로의 origptr·updptr를그립니다. 실제 mapping정의·permission정책·modulelifecycle은호출문맥을이어읽습니다.
 */
static void __apply_alternatives(const struct alt_region *region,
				 bool is_module,
				 unsigned long *cpucap_mask)
{
	struct alt_instr *alt;
	__le32 *origptr, *updptr;
	alternative_cb_t alt_cb;

	for (alt = region->begin; alt < region->end; alt++) {
		int nr_inst;
		int cap = ALT_CAP(alt);

		if (!test_bit(cap, cpucap_mask))
			continue;

		if (!cpus_have_cap(cap))
			continue;

		if (ALT_HAS_CB(alt))
			BUG_ON(alt->alt_len != 0);
		else
			BUG_ON(alt->alt_len != alt->orig_len);

		origptr = ALT_ORIG_PTR(alt);
		updptr = is_module ? origptr : lm_alias(origptr);
		nr_inst = alt->orig_len / AARCH64_INSN_SIZE;

