/* 학습 해설
 * Alternative VDSO·ELFsection에서region복원
 * 원본300행의주소복원·분기와page재배치·callback·mask·alias·cache·ELFregion·boot/system/module동기화와사용계약을읽습니다.
 * VDSO적용은 all_capabilities를채우고 ELFheader의 sectionheader주소를얻어.altinstructions를찾습니다. section이없으면바로반환하고있으면 VDSObase+sh_offset부터+sh_size까지 region을만듭니다. 이후 kernel형식의 falseis_module로적용 helper를호출합니다.
 * ELF파일 offset과 runtimebase를연결하는주소계산을그립니다. find_section구현·잘못된 ELF전체검증·실제 VDSO메모리 mapping은이함수본문밖입니다.
 */
static void __init apply_alternatives_vdso(void)
{
	struct alt_region region;
	const struct elf64_hdr *hdr;
	const struct elf64_shdr *shdr;
	const struct elf64_shdr *alt;
	DECLARE_BITMAP(all_capabilities, ARM64_NCAPS);

	bitmap_fill(all_capabilities, ARM64_NCAPS);

	hdr = (struct elf64_hdr *)vdso_start;
	shdr = (void *)hdr + hdr->e_shoff;
	alt = find_section(hdr, shdr, ".altinstructions");
	if (!alt)
		return;

	region = (struct alt_region){
		.begin	= (void *)hdr + alt->sh_offset,
		.end	= (void *)hdr + alt->sh_offset + alt->sh_size,
	};

	__apply_alternatives(&region, false, &all_capabilities[0]);
}

