 * kernel_alternatives는 linker가제공하는__alt_instructions와끝 symbol을 begin/end로연결한 initconstregion입니다. range는 descriptor단위로 loop에서소비합니다. 배열의개수상수보다 linkersection경계를사용해여러번역단위가만든 metadata를모으는기술입니다.
 * Cstruct배열과 linkersection시작/끝 symbol의관계를그립니다. 이파일이모든 descriptor본문을직접선언한것처럼해석하지않습니다.
 */
static const struct alt_region kernel_alternatives __initconst = {
	.begin	= (struct alt_instr *)__alt_instructions,
	.end	= (struct alt_instr *)__alt_instructions_end,
};

/*
 * We might be patching the stop_machine state machine, so implement a
 * really simple polling protocol here.
 */
static int __init __apply_alternatives_multi_stop(void *unused)
{
	/* We always have a CPU 0 at this point (__init) */
	if (smp_processor_id()) {
		while (!all_alternatives_applied)
			cpu_relax();
		isb();
	} else {
		DECLARE_BITMAP(remaining_capabilities, ARM64_NCAPS);

		bitmap_complement(remaining_capabilities, boot_cpucaps,
				  ARM64_NCAPS);

		BUG_ON(all_alternatives_applied);
		__apply_alternatives(&kernel_alternatives, false,
				     remaining_capabilities);
		/* Barriers provided by the cache flushing */

/* 학습 해설
 * Alternative multi-stop·CPU0작업과단순poll
 * 원본300행의주소복원·분기와page재배치·callback·mask·alias·cache·ELFregion·boot/system/module동기화와사용계약을읽습니다.
 * CPU0이아닌 CPU는 volatileall_alternatives_applied를 poll하며 cpu_relax하고완료후 isb합니다. CPU0은 boot_cpucaps의 complement인 remaining집합을만들어아직전체적용전임을 BUG_ON으로확인하고패치후완료 flag1을씁니다. stop_machine자체도패치대상일수있어단순 pollprotocol을쓴다는주석이있습니다.
 * CPU0패치·cachebarrier·flagpublish와다른 CPUwait·isb를그립니다. volatile하나만으로임의멀티스레드 memoryordering이보장된다는일반화를하지않습니다.
 */
static int __init __apply_alternatives_multi_stop(void *unused)
{
	/* We always have a CPU 0 at this point (__init) */
	if (smp_processor_id()) {
		while (!all_alternatives_applied)
			cpu_relax();
		isb();
	} else {
		DECLARE_BITMAP(remaining_capabilities, ARM64_NCAPS);

		bitmap_complement(remaining_capabilities, boot_cpucaps,
				  ARM64_NCAPS);

		BUG_ON(all_alternatives_applied);
		__apply_alternatives(&kernel_alternatives, false,
				     remaining_capabilities);
		/* Barriers provided by the cache flushing */
		all_alternatives_applied = 1;
	}

	return 0;
}

void __init apply_alternatives_all(void)
{
	pr_info("applying system-wide alternatives\n");

/* 학습 해설
 * Alternative 전체적용·VDSO와stop_machine
 * 원본300행의주소복원·분기와page재배치·callback·mask·alias·cache·ELFregion·boot/system/module동기화와사용계약을읽습니다.
 * 전체적용은먼저 VDSO를처리하고 cpu_online_mask를대상으로 stop_machine에 multi_stopcallback을넘깁니다. liveSMP에서다른 CPU가패치중 instruction을동시에실행하는문제를피하려는호출문맥입니다. stop_machine알고리즘전체는이함수호출한줄에구현된것이아닙니다.
 * VDSO→systemstopcallback→CPU0patch/다른 CPUwait흐름을연결합니다. actualstop_machine코드는다른파일학습으로이어집니다.
 */
void __init apply_alternatives_all(void)
{
	pr_info("applying system-wide alternatives\n");

	apply_alternatives_vdso();
	/* better not try code patching on a live SMP system */
	stop_machine(__apply_alternatives_multi_stop, NULL, cpu_online_mask);
}

/*
 * This is called very early in the boot process (directly after we run
 * a feature detect on the boot CPU). No need to worry about other CPUs
 * here.
 */
void __init apply_boot_alternatives(void)
{
	/* If called on non-boot cpu things could go wrong */
	WARN_ON(smp_processor_id() != 0);

	pr_info("applying boot alternatives\n");

	__apply_alternatives(&kernel_alternatives, false,
			     &boot_cpucaps[0]);
}

