noinstr void alt_cb_patch_nops(struct alt_instr *alt, __le32 *origptr,
			       __le32 *updptr, int nr_inst)
{
	for (int i = 0; i < nr_inst; i++)
		updptr[i] = cpu_to_le32(aarch64_insn_gen_nop());
}
EXPORT_SYMBOL(alt_cb_patch_nops);

/* 학습 해설
 * Alternative NOPcallback·정확히nr_inst개생성
 * 원본300행의주소복원·분기와page재배치·callback·mask·alias·cache·ELFregion·boot/system/module동기화와사용계약을읽습니다.
 * NOPcallback은 origptr자료를복사하지않고 aarch64_insn_gen_nop로 instructionword를생성해 nr_inst개 updptr에 little-endian으로씁니다. kernellikelycapability의 branch를 NOP으로바꾸는 callback과연결됩니다. prototype의 descriptor·orig인자가여기서사용되지않아도공통인터페이스는유지합니다.
 * fixture의 2wordNOP생성과 3번째 sentinel보존을확인합니다. 생성된 word를 kerneltext에실제로써실행한검증으로해석하지않습니다.
 */
noinstr void alt_cb_patch_nops(struct alt_instr *alt, __le32 *origptr,
			       __le32 *updptr, int nr_inst)
{
	for (int i = 0; i < nr_inst; i++)
		updptr[i] = cpu_to_le32(aarch64_insn_gen_nop());
}
EXPORT_SYMBOL(alt_cb_patch_nops);

